import django.db.models.deletion
from django.db import migrations, models


def link_existing_venues(apps, schema_editor):
    """Create a building for each place named in the venues' locations.

    "Level 3, AIKOL Main Building" and "AIKOL Main Building" become one
    building. The location text itself is left exactly as it was.
    """
    import re

    Building = apps.get_model("resources", "Building")
    Venue = apps.get_model("resources", "Venue")
    for venue in Venue.objects.filter(building__isnull=True):
        parts = [part.strip() for part in (venue.location or "").split(",") if part.strip()]
        if len(parts) > 1 and re.match(r"^(level|floor|aras|tingkat)\b", parts[0], re.I):
            parts = parts[1:]
        name = ", ".join(parts)[:80]
        if not name:
            continue
        building = Building.objects.filter(name__iexact=name).first()
        if building is None:
            building = Building.objects.create(name=name)
        venue.building = building
        venue.save(update_fields=["building"])


